SET ROLE hub2_authz_owner;
CREATE TABLE authz.security_state(id boolean PRIMARY KEY DEFAULT true CHECK(id),era uuid NOT NULL DEFAULT gen_random_uuid());
INSERT INTO authz.security_state DEFAULT VALUES;
CREATE TABLE authz.principals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('member','service')),display_name text NOT NULL,role text NOT NULL DEFAULT 'member' CHECK(role IN ('member','organization_admin')),active boolean NOT NULL DEFAULT true,epoch bigint NOT NULL DEFAULT 1 CHECK(epoch>0),trusted_source text NOT NULL CHECK(length(trusted_source)>0));
CREATE TABLE authz.clients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),principal_id uuid NOT NULL REFERENCES authz.principals, label text NOT NULL,active boolean NOT NULL DEFAULT true,epoch bigint NOT NULL DEFAULT 1,actions text[] NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE authz.credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_id uuid NOT NULL REFERENCES authz.clients,token_hash text NOT NULL UNIQUE CHECK(token_hash ~ '^[0-9a-f]{64}$'),expires_at timestamptz,until_revoked boolean NOT NULL DEFAULT false,revoked_at timestamptz,epoch bigint NOT NULL DEFAULT 1,CHECK((expires_at IS NULL)=until_revoked));
CREATE TABLE authz.sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),principal_id uuid NOT NULL REFERENCES authz.principals,token_hash text NOT NULL UNIQUE,refresh_hash text UNIQUE,expires_at timestamptz NOT NULL,refresh_expires_at timestamptz NOT NULL,revoked_at timestamptz,epoch bigint NOT NULL DEFAULT 1);
CREATE TABLE authz.qualifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),principal_id uuid NOT NULL REFERENCES authz.principals,project_id uuid NOT NULL,actions text[] NOT NULL,source_actor_id uuid NOT NULL REFERENCES authz.principals,parent_id uuid REFERENCES authz.qualifications,kind text NOT NULL CHECK(kind IN ('work','management')),depth integer NOT NULL DEFAULT 0 CHECK(depth BETWEEN 0 AND 1),expires_at timestamptz,until_revoked boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,epoch bigint NOT NULL DEFAULT 1,source_project_revision bigint NOT NULL,CHECK((expires_at IS NULL)=until_revoked),CHECK((parent_id IS NULL AND depth=0) OR (parent_id IS NOT NULL AND depth=1)));
CREATE TABLE authz.source_contexts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),principal_id uuid NOT NULL REFERENCES authz.principals,client_id uuid NOT NULL REFERENCES authz.clients,provider text NOT NULL,native_key text,assurance text NOT NULL DEFAULT 'self_reported',envelope jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(principal_id,client_id,provider,native_key));
CREATE TABLE authz.handles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),principal_id uuid NOT NULL REFERENCES authz.principals,client_id uuid NOT NULL REFERENCES authz.clients,credential_id uuid NOT NULL REFERENCES authz.credentials,audience text NOT NULL CHECK(audience IN ('mem','v8','worker')),action text NOT NULL,project_id uuid NOT NULL,resource jsonb NOT NULL,request_digest text NOT NULL CHECK(request_digest ~ '^[0-9a-f]{64}$'),source_context_id uuid REFERENCES authz.source_contexts,security_era uuid NOT NULL,principal_epoch bigint NOT NULL,client_epoch bigint NOT NULL,credential_epoch bigint NOT NULL,project_revision bigint,expires_at timestamptz NOT NULL,consumed_at timestamptz);
ALTER TABLE authz.handles ADD consumed_xid xid8;
CREATE TABLE authz.operations(principal_id uuid NOT NULL,idempotency_key text NOT NULL,request_digest text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(principal_id,idempotency_key));
REVOKE ALL ON ALL TABLES IN SCHEMA authz FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;
RESET ROLE;
